// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/accounts", wrapper.ListAccounts)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/accounts/{id}", wrapper.GetAccount)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/accounts/{id}/certificate", wrapper.UploadCertificate)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/{id}/pause", wrapper.PauseAccount)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/{id}/resume", wrapper.ResumeAccount)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/accounts/{id}/scan", wrapper.RequestScan)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/accounts/{id}/notes", wrapper.ListNotes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/notes/{id}/xml", wrapper.GetNoteXML)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/notes/{id}/events", wrapper.ListNoteEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/notes/{id}/ciencia", wrapper.RequestCiencia)

	return m
}

